<?php $heading='Pendaftar Lowongan';$kicker='REKRUTMEN · KANDIDAT';$subtitle='Tinjau profil, periksa berkas, dan lanjutkan kandidat ke tahap berikutnya.';require ROOT.'/app/Views/components/heading.php';?>
<section class="card"><form class="filters inline-filters" method="get" action="index.php"><input type="hidden" name="r" value="pendaftar"><label>Pencarian<input name="keyword" value="<?= e(query('keyword')) ?>" placeholder="Nama, NIM, atau posisi"></label><label>Lowongan<select name="lowongan"><option value="">Semua lowongan</option><?php foreach($lowongan as $l):?><option value="<?= $l['idLowongan'] ?>"<?= selected(query('lowongan'),$l['idLowongan']) ?>><?= e($l['namaLowongan']) ?></option><?php endforeach;?></select></label><label>Status<select name="status"><option value="">Semua status</option><?php foreach(['Lamaran Terkirim','Diproses','Wawancara','Diterima','Ditolak'] as $s):?><option<?= selected(query('status'),$s) ?>><?= e($s) ?></option><?php endforeach;?></select></label><button class="button">Terapkan</button><a class="button text" href="<?= e(url('pendaftar')) ?>">Reset</a></form></section>
<section class="card"><div class="section-heading"><h2>Daftar kandidat</h2><span class="badge blue"><?= count($pendaftar) ?> pendaftar</span></div><div class="table-scroll"><table><thead><tr><th>Mahasiswa</th><th>Lowongan</th><th>Program Studi</th><th>Tanggal Melamar</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($pendaftar as $a):?><tr><td><strong><?= e($a['namaMahasiswa']) ?></strong><small><?= e($a['NIM']) ?></small></td><td><?= e($a['namaLowongan']) ?></td><td><?= e($a['jurusan']) ?><small>Semester <?= e($a['semester']) ?> · IPK <?= e($a['IPK']) ?></small></td><td><?= tanggal($a['tanggalMelamar']) ?></td><td><?= badge($a['statusLamaran']) ?></td><td><a class="button secondary small" href="<?= e(url('seleksi/detail',['id'=>$a['idLamaran']])) ?>">Tinjau <?= icon('arrow') ?></a></td></tr><?php endforeach;?></tbody></table></div><?php if(!$pendaftar):?><div class="empty-state"><?= icon('user') ?><h3>Belum ada kandidat yang sesuai</h3><p>Lamaran yang dikirim mahasiswa akan tampil di sini.</p></div><?php endif;?></section>
